use serde_json::{Value, Number};

pub fn solve(input: Value) -> Value {
    match input {
        Value::Number(num) => {
            if let Some(cents) = num.as_i64() {
                let pounds = cents / 100;
                let remainder = cents % 100;
                let mut result = Number::from(pounds);
                if remainder != 0 {
                    result = Number::from_f64((pounds as f64) + (remainder as f64) / 100.0).unwrap();
                }
                Value::Number(result)
            } else {
                input
            }
        }
        _ => input,
    }
}
